-- 2147483648
SELECT LEAGUE.NAME FROM MATCH INNER JOIN LEAGUE ON MATCH.LEAGUE_ID = LEAGUE.ID WHERE MATCH.SEASON = '2015/2016' GROUP BY LEAGUE.NAME ORDER BY COUNT(MATCH.ID) DESC LIMIT 4;
-- ----------sql2------------
